 function calculateLine(current,patch){
  const next={...current,...patch};
  if(["MATERIALS","VENUE/FOOD","PATIENT EXPENSE"].includes(next.category)){next.amount=Math.round(Number(next.quantity||0)*Number(next.unit_price||0)*100)/100;}
   if(next.category==="HONORARIA"){next.amount=Math.round(Number(next.rate_per_hour||0)*Number(next.hours||0)*100)/100;}
   if(next.category==="PS"&&next.position){
   const rate=salaryRates.find(r=>r.position===next.position);
   if(rate){
    next.salary_grade=String(rate.salaryGrade);
    next.hourly_rate=Number(rate.hourlyRate);
    const multiplier=Number(next.patients)>0?Number(next.patients):1;
    next.amount=Math.round(Number(next.hourly_rate)*Number(next.hours||0)*Number(next.staff_count||0)*multiplier*100)/100;
    next.item=next.position;
   }
  }
  return next;
 }
 function updateBudget(patch){setBudget(current=>calculateLine(current,patch));}
